def chunk_words(text, size):
    if not isinstance(size, int) or size <= 0:
        return []
    words = text.split()
    if not words:
        return []
    chunks = []
    for i in range(0, len(words), size):
        chunks.append(' '.join(words[i:i + size]))
    return chunks

def build_chunk_records(chunks, source_id):
    result = []
    for idx, text in enumerate(chunks, start=1):
        result.append({
            'chunk_id': f'{source_id}#{idx}',
            'source_id': source_id,
            'text': text,
        })
    return result

def filter_records(records, filters):
    if not filters:
        return list(records)
    result = []
    for record in records:
        if all(record.get(k) == v for k, v in filters.items()):
            result.append(record)
    return result

def rerank(candidates):
    return sorted(
        candidates,
        key=lambda c: c.get('vector_score', 0) + 0.1 * c.get('keyword_hits', 0),
        reverse=True,
    )

def build_answer(text, used_chunks):
    citations = []
    seen = set()
    for cid in used_chunks:
        if cid not in seen:
            seen.add(cid)
            citations.append(cid)
    return {
        'answer': text,
        'citations': citations,
    }

