class MiniRagPipeline:
    def __init__(self):
        self._chunks = []

    def add_document(self, text, max_words):
        words = text.split()
        if not words or max_words <= 0:
            return []
        new_chunks = []
        for i in range(0, len(words), max_words):
            new_chunks.append(' '.join(words[i:i + max_words]))
        self._chunks.extend(new_chunks)
        return new_chunks

    def score_relevance(self, chunk, query):
        return len(set(chunk.lower().split()) & set(query.lower().split()))

    def retrieve_top_k(self, query, k):
        scored = [(c, self.score_relevance(c, query)) for c in self._chunks]
        scored.sort(key=lambda x: x[1], reverse=True)
        return [c for c, _ in scored[:k]]

    def build_prompt(self, question, chunks):
        context = '\n'.join(f'- {chunk}' for chunk in chunks)
        return f'Context:\n{context}\n\nQuestion: {question}'

    def format_citation(self, source, idx):
        return f'[{idx}] {source}'
